class JLNumeric(Numeric):
    """Julia numeric wrapper."""


class JLLibRoutineVariable(LibRoutineVariable):
    """Julia-side routine variable behaviour."""

    DTYPE_LOOKUP = {
        "f64": "Float64",
        "f32": "Float32",
        "i64": "Int64",
        "i32": "Int32",
    }

    def lookup_dtype(self, dtype):
        if dtype in type(self).DTYPE_LOOKUP:
            return type(self).DTYPE_LOOKUP[dtype]
        raise ValueError(f"Unknown dtype: {dtype}")

    def expr_at(self, offset_string):
        return f"{self.name}[({offset_string}) + 1]"

    def get_zero_value(self):
        return f"{self.lookup_dtype(self.dtype)}(0)"

    def get_definition_lines(self):
        if self.is_scalar:
            yield f"{self._name} = {self.get_zero_value()}"
            return
        yield (
            f"{self._name} = zeros({self.lookup_dtype(self.dtype)}, {self._size})"
        )

    def generate_tozero_lines(self):
        zero_value = self.get_zero_value()
        if self.is_scalar:
            yield f"{self.expr()} = {zero_value}"
            return
        yield f"{self.name} .= {zero_value}"


class JLLocalVariable(JLLibRoutineVariable, LibRoutineLocalVariable):
    """Julia local variable."""


class JLDummyVariable(JLLibRoutineVariable):
    """Base class for Julia routine arguments."""

    _intent = None

    def as_argument_declaration(self):
        return self._name

    def get_definition_lines(self):
        return
        yield

    def expr(self):
        if self.is_scalar and type(self)._intent in {"WO", "RW"}:
            return f"{self.name}[]"
        return super().expr()


class JLInputVariable(JLDummyVariable, LibRoutineInputVariable):
    """Read-only Julia routine argument."""

    _intent = "RO"


class JLOutputVariable(JLDummyVariable, LibRoutineOutputVariable):
    """Write-only Julia routine argument."""

    _intent = "WO"


class JLInOutVariable(JLDummyVariable, LibRoutineInOutVariable):
    """Read-write Julia routine argument."""

    _intent = "RW"


class JLBufferVariable(JLInOutVariable, LibRoutineBufferVariable):
    """Buffer-backed Julia routine argument."""

    _intent = "RW"


class JLConstant(JLLibRoutineVariable, LibRoutineConstant):
    """Julia constant definition."""

    def get_definition_lines(self):
        if self.is_scalar:
            yield f"const {self._name} = {self.lookup_dtype(self.dtype)}({self.value!r})"
            return
        yield (
            f"const {self._name} = {self.lookup_dtype(self.dtype)}[{', '.join(repr(value) for value in self.values)}]"
        )


class JLAssignmentStatementLine(AssignmentStatementLine):
    """Julia assignment statement rendering."""

    BLUEPRINT = "{target} = {expression}"


class JLAccumulateStatementLine(AccumulateStatementLine):
    """Julia in-place accumulation statement rendering."""

    UPDATE_BLUEPRINT = "{target} += {expression}"


class JLRoutineCallContainer(RoutineCallContainer):
    """Julia function-call emission container."""

    def get_call_string(self):
        return f"{self.get_call_name()}({', '.join(self.get_args_list())})"


class JLCommentLine(CommentLine):
    """Julia comment line rendering."""

    COMMENT_PREFIX = "# "


class JLImportContainer(ImportContainer):
    """Julia import emission container."""

    INDENT_BODY = False

    def construct_code_lines(self, **_):
        names = ", ".join(routine.name for routine in self.routines)
        yield f"import .{self.library.libname}: {names}"


class JLBackendImportContainer(CodeLine):
    """Comment-style description of the compiled backend in wrapper mode."""

    def __init__(self, backend_library, *, context, **params):
        super().__init__(context=context, **params)
        self._backend_library = backend_library

    def construct_code_lines(self, **_):
        kind = JuliaBuilder.identify_backend(self._backend_library)
        yield f"# BACKEND {kind} SOURCE {self._backend_library.filename}"
        if isinstance(self._backend_library, CLibrary):
            yield (
                f"# BACKEND {kind} HEADER {self._backend_library.headername}"
            )
        if isinstance(self._backend_library, FortranLibrary):
            yield f"# BACKEND {kind} MODULE {self._backend_library.libname}"


class JLImportSectionContainer(ImportSectionContainer):
    """Julia import section using plain routine names."""

    def compose_call_name(self, importable, library):
        del library
        return importable.name


class JLMultiFrameExpandContainer(MultiFrameExpandContainer):
    """Lower multiframe ranges to Julia ``for`` loops."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = JLLocalVariable

    def generate_head_containers(self):
        if self._multiframe_variable is not None:
            expr = self._multiframe_variable.expr()
            end_val = self._max_value - 1
            yield from self.codelines_from_text(
                f"for {expr} in {self._min_value}:{end_val}"
            )

    def generate_foot_containers(self):
        yield from self.codelines_from_text("end")


class JLIntCombineExpandContainer(IntCombineExpandContainer):
    """Combine split loop indices back into a single Julia index."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = JLLocalVariable

    def generate_head_containers(self, **_):
        expression = (
            f"{self._second.local} * {self._first.max_value}"
            f" + {self._first.local}"
        )
        if self._multiframe_variable.min_value:
            expression += f" + {self._multiframe_variable.min_value}"
        yield from self.codelines_from_text(
            f"{self._multiframe_variable.local} = {expression}"
        )
        yield from self.codelines_from_text(
            f"if {self._multiframe_variable.local} < {self._multiframe_variable.max_value}"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text("end")


class JLRoutineContainer(RoutineContainer):
    """Julia function container."""

    INDENT_BODY = True
    INPUT_VARIABLE_CLASS = JLInputVariable

    def get_signature(self):
        call_args = list(
            variable.as_argument_declaration()
            for variable in self.get_argument_variables()
        )
        return f"function {self.name}({', '.join(call_args)})"

    def generate_head_containers(self, **_):
        yield from self.codelines_from_text(self.get_signature())

    def generate_prmb_containers(self, **kwargs):
        local_variables = list(self.get_local_variables())
        if local_variables:
            yield from self.comment_from_text("LOCAL") or []
            for variable in local_variables:
                yield DefinitionLines(variable, context=self.context, **kwargs)
            yield from self.codelines_from_text("")

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text("end")


class JuliaLibRoutine(LibRoutine):
    """Julia library routine entry, optionally backed by a compiled routine."""

    def __init__(self, *args, backend_routine=None, **kwargs):
        super().__init__(*args, **kwargs)
        self._backend_routine = backend_routine

    @property
    def backend_routine(self):
        return self._backend_routine


class JuliaComputeResource(ComputeResource):
    """Compute resource that expands multiframes into Julia loops."""

    DEFAULT_LOCAL_VARIABLE_CLASS = JLLocalVariable

    def create_mfe_container(
        self, *, context, local_variable_capture, loop_capture=None
    ) -> None | MultiFrameExpandContainer:
        del loop_capture
        return JLMultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def create_combine_container(
        self,
        first,
        second,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ) -> None | MultiFrameExpandContainer:
        del name
        del loop_container
        del loop_capture
        return JLIntCombineExpandContainer(
            first,
            second,
            context=context,
            local_variable_capture=local_variable_capture,
        )


class JuliaBuilder(PyBuilder, identifier="JULIA"):
    """Julia builder with optional compiled-backend selector utilities."""

    BACKEND_LIBRARY_LOOKUP = {
        "C": CLibrary,
        "FORTRAN": FortranLibrary,
    }

    @staticmethod
    def normalize_backend_builder(backend_builder):
        """Normalize backend builder selectors to a builder class or ``None``."""
        if backend_builder is None:
            return None
        if isinstance(backend_builder, Builder):
            return type(backend_builder)
        if isinstance(backend_builder, type) and issubclass(
            backend_builder, Builder
        ):
            return backend_builder
        raise TypeError(
            "backend_builder must be None, a Builder instance, or a Builder subclass"
        )

    @classmethod
    def identify_backend(cls, backend):
        """Return ``None``, ``C``, or ``FORTRAN`` for a backend selector."""
        if backend is None:
            return None
        if isinstance(backend, CLibrary):
            return "C"
        if isinstance(backend, FortranLibrary):
            return "FORTRAN"
        backend_builder = cls.normalize_backend_builder(backend)
        if backend_builder is None:
            return None
        if issubclass(backend_builder, CBuilder):
            return "C"
        if issubclass(backend_builder, FortranBuilder):
            return "FORTRAN"
        raise ValueError(f"unsupported Julia backend builder: {backend_builder}")

    @classmethod
    def create_backend_library(
        cls,
        plain_name,
        *,
        backend_builder=None,
        build_hash=None,
    ):
        """Create the compiled backend library selected for Julia wrapping."""
        kind = cls.identify_backend(backend_builder)
        if kind is None:
            return None
        library_class = cls.BACKEND_LIBRARY_LOOKUP[kind]
        return library_class(plain_name, build_hash=build_hash)

    def create_libroutine_variable(
        self,
        *,
        name,
        dtype,
        status,
        size,
        assignment=None,
        namespace=None,
        **kwargs,
    ):
        if status & LibRoutineVariable.STATUS_BUFFER:
            return JLBufferVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        status = status & 3
        if status == LibRoutineVariable.STATUS_INPUT:
            return JLInputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_OUTPUT:
            return JLOutputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_INOUT:
            return JLInOutVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        return super().create_libroutine_variable(
            name=name,
            dtype=dtype,
            status=status,
            size=size,
            assignment=assignment,
            namespace=namespace,
            **kwargs,
        )

    def create_local_variable(
        self, name, *, dtype, size=None, namespace=None, **kwargs
    ):
        return JLLocalVariable(
            name=name,
            dtype=dtype,
            size=size,
            namespace=namespace,
            **kwargs,
        )

    def create_external_array(
        self,
        array_name,
        values,
        *,
        dtype,
        namespace=None,
        constant_class=JLConstant,
        local_class=JLLocalVariable,
        **kwargs,
    ):
        return Builder.create_external_array(
            self,
            array_name,
            values,
            dtype=dtype,
            namespace=namespace,
            constant_class=constant_class,
            local_class=local_class,
            **kwargs,
        )

    def as_numeric(self, variable):
        return JLNumeric(variable)


class JuliaLibrary(Library):
    """Julia library in pure mode or compiled-backend wrapper mode."""

    BACKEND_IDENTIFIER = "julia"
    FILEENDING = "jl"
    INDENTSTR = "    "
    LIBROUTINE_CLASS = JuliaLibRoutine
    IMPORTLINE_CLASS = JLImportContainer
    DEFAULT_BUILDER = JuliaBuilder
    DEFAULT_CONTAINER_CLASS = JLRoutineContainer

    _CTYPE_LOOKUP = {
        "f64": ("Float64", "Cdouble"),
        "f32": ("Float32", "Cfloat"),
        "i32": ("Int32", "Cint"),
        "i64": ("Int64", "Clonglong"),
    }

    def __init__(
        self,
        plain_name,
        *,
        backend_builder=None,
        backend_library=None,
        build_hash=None,
        resource=None,
        configuration=None,
        general_configuration=None,
    ):
        backend_builder = JuliaBuilder.normalize_backend_builder(
            backend_builder
        )
        if resource is None:
            resource = JuliaComputeResource("JuliaResource")
        super().__init__(
            plain_name,
            build_hash=build_hash,
            resource=resource,
            configuration=configuration,
            general_configuration=general_configuration,
        )

        if backend_library is None:
            backend_library = JuliaBuilder.create_backend_library(
                plain_name,
                backend_builder=backend_builder,
                build_hash=build_hash,
            )

        self._backend_builder_class = backend_builder
        self._backend_library = backend_library
        if backend_library is not None:
            self._dependencies.add(backend_library)

    @property
    def is_wrapper_mode(self):
        return self._backend_library is not None

    @property
    def backend_library(self):
        return self._backend_library

    @property
    def backend_kind(self):
        return JuliaBuilder.identify_backend(self.backend_library)

    @property
    def sharedlibname(self):
        return self._get_sharedlibname()

    def _get_sharedlibname(self):
        return f"lib{self.libname}_julia.so"

    @property
    def shim_source_name(self):
        return self._get_shim_source_name()

    def _get_shim_source_name(self):
        return f"{self.libname}_julia_shim.f90"

    def get_to_zero_support_routine(self, dtype):
        """Return the external helper routine used to reset one buffer."""
        routine_name = f"phoenix_to_zero_{dtype}"
        existing = self[routine_name]
        if existing is not None:
            return existing
        zero_value = JLLocalVariable(name="tmp", dtype=dtype, no_entry=True).get_zero_value()
        code = [
            f"function {routine_name}(buffer, size)",
            "    for idx in 1:size",
            f"        buffer[idx] = {zero_value}",
            "    end",
            "end",
        ]
        return self._register_manual_routine(
            routine_name,
            code=code,
            arguments=[
                {
                    "name": "buffer",
                    "dtype": dtype,
                    "size": 1,
                    "status": "INOUT",
                    "assignment": ("buffer", "data"),
                },
                {
                    "name": "size",
                    "dtype": "i32",
                    "status": "IN",
                },
            ],
        )

    def _backend_source_libraries(self):
        if self.backend_library is None:
            return []
        dependencies = list(
            self.backend_library.get_dependencies(
                recursive=True,
                ignore_self=True,
            )
        )
        dependencies.reverse()
        return [*dependencies, self.backend_library]

    def _backend_source_files(self):
        return [library.filename for library in self._backend_source_libraries()]

    def _wrapper_source_files(self):
        if self.backend_kind == "FORTRAN":
            return [*self._backend_source_files(), self.shim_source_name]
        return self._backend_source_files()

    def _detect_backend_builder(self, builder):
        if not self.is_wrapper_mode:
            if builder is None:
                return None
            backend_builder = JuliaBuilder.normalize_backend_builder(builder)
            if backend_builder is not None:
                raise ValueError(
                    "Pure Julia libraries do not accept a compiled backend builder"
                )
            return None

        backend_builder = builder
        if backend_builder is None:
            backend_builder = self._backend_builder_class
        backend_builder = JuliaBuilder.normalize_backend_builder(
            backend_builder
        )
        expected_kind = self.backend_kind
        actual_kind = JuliaBuilder.identify_backend(backend_builder)
        if actual_kind != expected_kind:
            raise ValueError(
                f"Julia wrapper library {self.libname} is bound to {expected_kind}, "
                f"but received routine builder {actual_kind}"
            )
        return backend_builder

    def prepare_sections(self, **kwargs):
        if self.backend_library is not None:
            self._dependencies.add(self.backend_library)
        return super().prepare_sections(**kwargs)

    def libroutine_from_instructions(
        self,
        name,
        *instructions,
        builder=None,
        daa_assignments=None,
        lrv_assignments=None,
        container_class=None,
        namespace=None,
        resource=None,
        **buildargs,
    ):
        backend_builder = self._detect_backend_builder(builder)
        if backend_builder is None:
            return super().libroutine_from_instructions(
                name,
                *instructions,
                builder=builder,
                daa_assignments=daa_assignments,
                lrv_assignments=lrv_assignments,
                container_class=container_class,
                namespace=namespace,
                resource=resource,
                **buildargs,
            )

        backend_routine = self.backend_library.libroutine_from_instructions(
            name,
            *instructions,
            builder=backend_builder(f"default:lib{name}"),
            daa_assignments=daa_assignments,
            lrv_assignments=lrv_assignments,
            container_class=container_class,
            namespace=namespace,
            resource=resource,
            **buildargs,
        )
        return self.create_libroutine_entry(
            name=name,
            arguments=list(backend_routine.get_arguments()),
            container=backend_routine.container,
            lrv_assignments=lrv_assignments,
            daa_assignments=daa_assignments,
            backend_routine=backend_routine,
        )

    def create_libroutine_entry(
        self,
        name,
        arguments,
        container,
        lrv_assignments,
        daa_assignments=None,
        backend_routine=None,
    ):
        libroutine = type(self).LIBROUTINE_CLASS(
            name,
            library=self,
            arguments=arguments,
            container=container,
            lrv_assignments=lrv_assignments,
            daa_assignments=daa_assignments,
            backend_routine=backend_routine,
        )
        self.append_libroutine(libroutine)
        return libroutine

    def generate_head_containers(self, **_):
        yield from self.codelines_from_text(f"module {self.libname}")
        yield from self.codelines_from_text("")

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(f"end # module {self.libname}")

    def generate_prmb_containers(self, **_):
        imports = list(self.import_capture.list_imports())
        if imports:
            yield from self.comment_from_text("IMPORTS") or []
            for library, routines in imports:
                yield JLImportContainer(library, routines, context=self.context)
            yield from self.codelines_from_text("")

        constants = list(self.definition_capture.captured)
        if constants:
            yield from self.comment_from_text("CONSTANTS") or []
            for variable in constants:
                for line in variable.get_definition_lines():
                    yield from self.codelines_from_text(line)
            yield from self.codelines_from_text("")

        exported = [routine.name for _name, routine in self.content]
        if exported:
            yield from self.codelines_from_text(
                f"export {', '.join(exported)}"
            )
            yield from self.codelines_from_text("")

    def generate_clsg_containers(self, **_):
        return
        yield

    def get_codelines(self, indent=0):
        if self.is_wrapper_mode:
            yield from self.get_wrapper_codelines(indent=indent)
            return

        yield from self.get_codelines_head(indent=indent)
        yield from self.get_codelines_prmb(indent=indent)
        for routine_container in self.routine_containers:
            yield from routine_container.get_codelines(indent=indent)
            yield indent, ""
        yield from self.get_codelines_foot(indent=indent)

    def _render_backend_comment_lines(self):
        importer = JLBackendImportContainer(
            self.backend_library, context=self.context
        )
        for indent, line in importer.get_codelines(indent=0):
            yield indent, line

    def _jl_type(self, dtype):
        return type(self)._CTYPE_LOOKUP[dtype][0]

    def _jl_ctype(self, dtype):
        return type(self)._CTYPE_LOOKUP[dtype][1]

    def _iter_return_args(self, routine):
        for arg in routine.get_arguments():
            if arg.status & arg.STATUS_OUTPUT:
                yield arg

    def _iter_input_args(self, routine):
        for arg in routine.get_arguments():
            if arg.status & arg.STATUS_INPUT:
                yield arg

    def _backend_symbol_name(self, routine):
        if self.backend_kind == "FORTRAN":
            return f"jl_{routine.name}"
        return routine.name

    def _render_wrapper_helper_methods(self, indent):
        yield indent, "function backend_library_name()"
        yield indent + 1, f"return \"{self.sharedlibname}\""
        yield indent, "end"
        yield indent, ""
        yield indent, "function backend_library_path()"
        yield indent + 1, "return joinpath(@__DIR__, backend_library_name())"
        yield indent, "end"
        yield indent, ""
        yield indent, "function build_backend()"
        yield indent + 1, "this_dir = @__DIR__"
        yield indent + 1, "lib_path = backend_library_path()"
        yield indent + 1, (
            "sources = ["
            + ", ".join(
                f"joinpath(this_dir, \"{name}\")"
                for name in self._wrapper_source_files()
            )
            + "]"
        )
        if self.backend_kind == "FORTRAN":
            yield indent + 1, 'compiler = get(ENV, "FC", "gfortran")'
        else:
            yield indent + 1, 'compiler = get(ENV, "CC", "cc")'
        yield indent + 1, (
            "cmd = `"
            + "$compiler -shared -fPIC -o $lib_path $(sources...) -I$this_dir"
            + "`"
        )
        yield indent + 1, "run(cmd)"
        yield indent, "end"
        yield indent, ""
        yield indent, "function ensure_backend()"
        yield indent + 1, "if !isfile(backend_library_path())"
        yield indent + 2, "build_backend()"
        yield indent + 1, "end"
        yield indent + 1, "return backend_library_path()"
        yield indent, "end"
        yield indent, ""
        yield indent, "const _backend_handle = Ref{Ptr{Cvoid}}(C_NULL)"
        yield indent, ""
        yield indent, "function library_handle()"
        yield indent + 1, "if _backend_handle[] == C_NULL"
        yield indent + 2, "_backend_handle[] = Libdl.dlopen(ensure_backend())"
        yield indent + 1, "end"
        yield indent + 1, "return _backend_handle[]"
        yield indent, "end"

    def _ccall_signature_entry(self, arg):
        ctype = self._jl_ctype(arg.dtype)
        status = arg.status & 3
        if self.backend_kind == "FORTRAN":
            if arg.is_scalar:
                return f"Ref{{{ctype}}}"
            return f"Ptr{{{ctype}}}"
        if status == arg.STATUS_INPUT and arg.is_scalar:
            return ctype
        if arg.is_scalar:
            return f"Ref{{{ctype}}}"
        return f"Ptr{{{ctype}}}"

    def _render_wrapper_method(self, routine, indent):
        input_args = list(self._iter_input_args(routine))
        return_args = list(self._iter_return_args(routine))
        yield indent, (
            f"function {routine.name}({', '.join(arg.name for arg in input_args)})"
        )
        yield indent + 1, "lib = library_handle()"

        call_args = []
        return_exprs = []
        for arg in routine.get_arguments():
            jl_type = self._jl_type(arg.dtype)
            status = arg.status & 3

            if status == arg.STATUS_INPUT:
                if arg.is_scalar:
                    if self.backend_kind == "FORTRAN":
                        varname = f"{arg.name}_ref"
                        yield indent + 1, (
                            f"{varname} = Ref{{{jl_type}}}({jl_type}({arg.name}))"
                        )
                        call_args.append(varname)
                    else:
                        varname = f"{arg.name}_value"
                        yield indent + 1, (
                            f"{varname} = {jl_type}({arg.name})"
                        )
                        call_args.append(varname)
                else:
                    varname = f"{arg.name}_data"
                    yield indent + 1, (
                        f"{varname} = Vector{{{jl_type}}}({arg.name})"
                    )
                    call_args.append(varname)
                continue

            if status == arg.STATUS_INOUT:
                if arg.is_scalar:
                    varname = f"{arg.name}_ref"
                    yield indent + 1, (
                        f"{varname} = Ref{{{jl_type}}}({jl_type}({arg.name}))"
                    )
                    call_args.append(varname)
                    return_exprs.append(f"{varname}[]")
                else:
                    varname = f"{arg.name}_copy"
                    yield indent + 1, (
                        f"{varname} = Vector{{{jl_type}}}({arg.name})"
                    )
                    call_args.append(varname)
                    return_exprs.append(varname)
                continue

            if arg.is_scalar:
                varname = f"{arg.name}_ref"
                yield indent + 1, f"{varname} = Ref{{{jl_type}}}()"
                call_args.append(varname)
                return_exprs.append(f"{varname}[]")
            else:
                varname = f"{arg.name}_out"
                yield indent + 1, (
                    f"{varname} = Vector{{{jl_type}}}(undef, {arg.size})"
                )
                call_args.append(varname)
                return_exprs.append(varname)

        signature = ", ".join(
            self._ccall_signature_entry(arg) for arg in routine.get_arguments()
        )
        call_argument_string = ", ".join(call_args)
        yield indent + 1, (
            f"ccall((:{self._backend_symbol_name(routine)}, lib), Cvoid, "
            f"({signature}), {call_argument_string})"
        )

        if not return_exprs:
            yield indent + 1, "return nothing"
        elif len(return_exprs) == 1:
            yield indent + 1, f"return {return_exprs[0]}"
        else:
            yield indent + 1, f"return ({', '.join(return_exprs)})"
        yield indent, "end"

    def get_wrapper_codelines(self, indent=0):
        yield indent, f"module {self.libname}"
        yield indent, ""
        yield indent, "using Libdl"
        for cindent, line in self._render_backend_comment_lines():
            yield indent + cindent, line
        yield indent, ""
        yield from self._render_wrapper_helper_methods(indent)
        yield indent, ""
        exported = [routine.name for _name, routine in self.content]
        if exported:
            yield indent, f"export {', '.join(exported)}"
            yield indent, ""
        for _name, routine in self.content:
            yield from self._render_wrapper_method(routine, indent)
            yield indent, ""
        yield indent, f"end # module {self.libname}"

    def _render_fortran_shim_arg(self, arg):
        lookup = {
            "f64": "real(c_double)",
            "f32": "real(c_float)",
            "i32": "integer(c_int)",
            "i64": "integer(c_long_long)",
        }
        dtype = lookup[arg.dtype]
        intent_lookup = {
            arg.STATUS_INPUT: "in",
            arg.STATUS_OUTPUT: "out",
            arg.STATUS_INOUT: "inout",
        }
        intent = intent_lookup[arg.status & 3]
        if arg.is_scalar:
            return f"{dtype}, intent({intent}) :: {arg.name}"
        return f"{dtype}, intent({intent}) :: {arg.name}({arg.size})"

    def get_fortran_shim_lines(self):
        for _name, routine in self.content:
            yield (
                f"subroutine jl_{routine.name}("
                + ", ".join(arg.name for arg in routine.get_arguments())
                + f') bind(C, name="jl_{routine.name}")'
            )
            yield "    use iso_c_binding"
            yield f"    use {self.backend_library.libname}, only: {routine.name}"
            yield "    implicit none"
            for arg in routine.get_arguments():
                yield "    " + self._render_fortran_shim_arg(arg)
            yield (
                f"    call {routine.name}("
                + ", ".join(arg.name for arg in routine.get_arguments())
                + ")"
            )
            yield f"end subroutine jl_{routine.name}"
            yield ""

    def write_fortran_shim(self):
        if self.backend_kind != "FORTRAN":
            return
        self.write_basepath_file(
            self.shim_source_name,
            lines=self.get_fortran_shim_lines(),
        )

    def write_all_files(self):
        if self.is_wrapper_mode and self.backend_library is not None:
            self.backend_library.write(force=True)
        self.write_code()
        self.write_fortran_shim()
        self.write_docs()
        return True

    def build(self, makefile=None, force=False, compile=True):
        if self.backend_library is not None:
            self.backend_library.build(
                makefile=makefile, force=force, compile=compile
            )
        return super().build(makefile=makefile, force=force, compile=compile)

    def _makefile_backend_command(self):
        compiler = "$(FC)" if self.backend_kind == "FORTRAN" else "$(CC)"
        sources = [
            self.relative_to_basepath(name)
            for name in self._wrapper_source_files()
        ]
        quoted = " ".join(f'"{name}"' for name in sources)
        return (
            f'{compiler} -shared -fPIC -o "{self.relative_to_basepath(self.sharedlibname)}" '
            f'{quoted} -I"{Path(self.basepath).resolve()}"'
        )

    def get_library_target(self):
        if not self.is_wrapper_mode:
            return None
        dependencies = [
            MFTSource(self.relative_to_basepath(name))
            for name in self._wrapper_source_files()
        ]
        if self.backend_kind == "C":
            for library in self._backend_source_libraries():
                header_target = library.get_header_target()
                if header_target is not None:
                    dependencies.append(header_target)
        return MFTSpecial(
            self.relative_to_basepath(self.sharedlibname),
            dependencies=dependencies,
            commands=[self._makefile_backend_command()],
        )

    def get_makefile_targets(self):
        if self.backend_library is not None:
            yield from self.backend_library.get_makefile_targets()
        yield self.get_codefile_target()
        if self.backend_kind == "FORTRAN":
            yield MFTSource(self.relative_to_basepath(self.shim_source_name))
        library_target = self.get_library_target()
        if library_target is not None:
            yield library_target


JuliaBuilder.set_instruction_class_handler(
    AffineOperationInstruction, JuliaBuilder.handle_affine_instruction
)
JuliaBuilder.set_instruction_class_handler(
    BiLinearOperationInstruction, JuliaBuilder.handle_bilinear_instruction
)

JLRoutineContainer.set_comment_class(JLCommentLine)

JuliaBuilder.set_comment_class(JLCommentLine)
JuliaBuilder.set_routinecall_class(JLRoutineCallContainer)
